INSERT INTO profile (full_name, title, headline, summary, about, email, phone, location, linkedin, github, website, live_project, availability) VALUES ('Rohith Reddy', 'DevOps · Cloud · SRE Engineer', 'I build cloud infrastructure that deploys itself, heals itself, and tells me when it can''t.', 'DevOps, Cloud, and SRE-focused engineer with hands-on experience in AWS, Terraform, Kubernetes, Docker, CI/CD, Linux administration, and monitoring. Owner and operator of DevJops.com, a live production job portal on AWS EKS. Immediate joiner; open to relocation and remote work.', '["I''m a DevOps, Cloud & SRE engineer based in Bengaluru, focused on infrastructure that is automated, reliable, and observable. I provision AWS with Terraform, ship containers to Amazon EKS, and wire up CI/CD with GitHub Actions and Prometheus/Grafana monitoring.","I don''t just build in tutorials — I run DevJops.com, a live production job portal on AWS EKS, and own it end to end: infrastructure, deployments, scaling, DNS, load balancing, monitoring and reliability. Most recently I interned at LeMiCi IQ, automating IaC pipelines with drift detection, security scanning and approval gates.","My philosophy: every deployment should be automated, every failure should be observable, and every incident should leave the system better than it was found."]', 'rohiithh5@gmail.com', '+91 93984 31327', 'Bengaluru, India (open to relocation & remote)', 'https://www.linkedin.com/in/rohithreddyhh', 'https://github.com/rohithh55', 'https://rohithh75.netlify.app', 'https://devjops.com', 'Immediate joiner');
INSERT INTO experiences (company, role, location, start_date, end_date, is_current, sort_order, tags, bullets) VALUES ('LeMiCi IQ Pvt. Ltd.', 'DevOps Engineer Intern', 'Bengaluru, India', '2026-05-01T00:00:00.000Z', '2026-08-31T00:00:00.000Z', 0, 1, '["Terraform","IaC","CI/CD","Drift Detection","Security Scanning"]', '["Assisted in transitioning manual Infrastructure-as-Code (IaC) provisioning into automated deployment pipelines, reducing manual intervention and streamlining execution times.","Configured automated drift detection to monitor deployed infrastructure, helping identify configuration divergences and flag unexpected cloud resources.","Integrated automated security scanning and manual approval gates into the deployment pipeline to catch IaC misconfigurations and authorize production changes before release."]');
INSERT INTO experiences (company, role, location, start_date, end_date, is_current, sort_order, tags, bullets) VALUES ('Accenar Technologies Pvt. Ltd.', 'DevOps / Cloud Engineering Intern', 'Hyderabad, India', '2024-12-01T00:00:00.000Z', '2025-08-31T00:00:00.000Z', 0, 2, '["AWS","Terraform","Docker","ECR","Linux","Prometheus","Grafana","GitHub Actions"]', '["Provisioned AWS infrastructure including EC2, S3, VPC, IAM, and ECR using Terraform Infrastructure as Code (IaC).","Containerized applications using Docker; created Dockerfiles and managed image build and push workflows with Amazon ECR.","Administered Linux servers running Ubuntu and CentOS, including user management, SSH key management, cron jobs, and log analysis.","Supported Prometheus and Grafana monitoring for infrastructure visibility and assisted with CI/CD pipeline setup using GitHub Actions."]');
INSERT INTO projects (title, description, status, live_url, repo_url, sort_order, tags, bullets) VALUES ('DevJops.com — Production Job Portal', 'Full-stack React/Node.js job portal running live on Amazon EKS (ap-south-1). I own the whole stack, from Terraform to on-call.', 'Live', 'https://devjops.com', NULL, 1, '["AWS EKS","Terraform","GitHub Actions","Prometheus","Grafana","React","Node.js"]', '["Provisioned VPC, EKS cluster, node groups, S3, IAM and ECR using Terraform.","CI/CD with GitHub Actions: Docker image build → Amazon ECR push → Kubernetes deployment.","Prometheus and Grafana for cluster and application monitoring, alerting and observability.","Managed DNS, load balancing and auto-scaling to keep the app available under real user traffic."]');
INSERT INTO projects (title, description, status, live_url, repo_url, sort_order, tags, bullets) VALUES ('Self-Healing Kubernetes SRE Project', 'Python and Bash automation that detects unhealthy Kubernetes pods and triggers remediation, cutting manual recovery effort.', 'Completed', NULL, NULL, 2, '["Kubernetes","Python","Bash","Prometheus","Grafana"]', '["Detects unhealthy pods and triggers automated remediation.","Prometheus and Grafana for monitoring, alert visibility and Kubernetes reliability tracking."]');
INSERT INTO projects (title, description, status, live_url, repo_url, sort_order, tags, bullets) VALUES ('AWS Infrastructure as Code', 'Reusable Terraform for AWS networking, compute, IAM and container registry — the foundation behind my EKS work.', 'Completed', NULL, 'https://github.com/rohithh55/aws-infrastructure', 3, '["Terraform","AWS","VPC","IAM","ECR"]', '[]');
